-- ============================================================================
-- Contexta EMR  |  config.lab_analytes + config.lab_analyte_synonyms
-- Canonical analyte dictionary and synonym map for attachment intelligence.
--
-- Conventions followed:
--   * No ENUMs. Categoricals are VARCHAR validated against config.lookup_values.
--   * No practice_id: this is Contexta-owned reference data in the config schema.
--   * Soft delete via is_active. Audit columns on both tables.
--   * All matching is done on normalised text, never on the raw string.
--
-- Match order at extraction time:
--   1. exact match on match_key
--   2. match_key match within the same panel_group hint
--   3. trigram similarity above threshold  -> propose, do not auto-apply
--   4. no match -> flag as UNMAPPED for staff
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS config.lab_analytes (
    analyte_id          BIGSERIAL     PRIMARY KEY,
    analyte_code        VARCHAR(40)   NOT NULL UNIQUE,
    analyte_name        VARCHAR(160)  NOT NULL,
    panel_group         VARCHAR(40)   NOT NULL,
    default_unit        VARCHAR(30),
    alt_units           VARCHAR(120),
    result_type         VARCHAR(20)   NOT NULL DEFAULT 'NUMERIC',
    loinc_code          VARCHAR(20),
    display_order       INTEGER       NOT NULL DEFAULT 0,
    is_active           BOOLEAN       NOT NULL DEFAULT true,
    is_deleted          BOOLEAN       NOT NULL DEFAULT false,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    created_by          VARCHAR(60)   NOT NULL DEFAULT 'SEED',
    updated_at          TIMESTAMPTZ,
    updated_by          VARCHAR(60)
);

CREATE TABLE IF NOT EXISTS config.lab_analyte_synonyms (
    synonym_id          BIGSERIAL     PRIMARY KEY,
    analyte_code        VARCHAR(40)   NOT NULL,
    synonym_text        VARCHAR(160)  NOT NULL,
    match_key           VARCHAR(160)  NOT NULL,
    source              VARCHAR(30)   NOT NULL DEFAULT 'SEED',
    lab_partner_id      BIGINT,
    confidence_floor    NUMERIC(4,3)  NOT NULL DEFAULT 0.850,
    is_active           BOOLEAN       NOT NULL DEFAULT true,
    is_deleted          BOOLEAN       NOT NULL DEFAULT false,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    created_by          VARCHAR(60)   NOT NULL DEFAULT 'SEED',
    updated_at          TIMESTAMPTZ,
    updated_by          VARCHAR(60),
    CONSTRAINT uq_synonym_key UNIQUE (match_key, analyte_code)
);

CREATE INDEX IF NOT EXISTS ix_analyte_syn_code   ON config.lab_analyte_synonyms (analyte_code);
CREATE INDEX IF NOT EXISTS ix_analyte_syn_trgm   ON config.lab_analyte_synonyms USING gin (match_key gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_analyte_panel      ON config.lab_analytes (panel_group);

-- Normalisation used to build match_key. Apply the SAME function to any
-- incoming raw label before lookup, or matching will silently fail.
CREATE OR REPLACE FUNCTION config.fn_normalise_analyte_label(p_label TEXT)
RETURNS TEXT
LANGUAGE sql IMMUTABLE AS $$
    SELECT regexp_replace(
             regexp_replace(UPPER(TRIM(COALESCE(p_label,''))), '[^A-Z0-9]+', ' ', 'g'),
             '\s+', ' ', 'g');
$$;

-- ---------------------------------------------------------------------------
-- Canonical analytes
-- ---------------------------------------------------------------------------
ON CONFLICT (analyte_code) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Synonyms. match_key is generated, never typed by hand.
-- ---------------------------------------------------------------------------
ON CONFLICT (match_key, analyte_code) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Lookup used by the extraction service.
-- Returns an exact hit, or the closest trigram candidates for staff to choose.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION config.fn_resolve_analyte(
    p_raw_label   TEXT,
    p_panel_hint  VARCHAR(40) DEFAULT NULL,
    p_threshold   NUMERIC     DEFAULT 0.45
)
RETURNS TABLE (
    analyte_code   VARCHAR(40),
    analyte_name   VARCHAR(160),
    panel_group    VARCHAR(40),
    default_unit   VARCHAR(30),
    match_type     VARCHAR(20),
    score          NUMERIC
)
LANGUAGE plpgsql AS $$
DECLARE
    v_key  TEXT := config.fn_normalise_analyte_label(p_raw_label);
    v_hits INTEGER;
BEGIN
    RETURN QUERY
    SELECT COUNT(*) INTO v_hits
    FROM   config.lab_analyte_synonyms s
    JOIN   config.lab_analytes a ON a.analyte_code = s.analyte_code
    WHERE  s.match_key = v_key
      AND  s.is_active AND NOT s.is_deleted AND a.is_active AND NOT a.is_deleted
      AND  (p_panel_hint IS NULL OR UPPER(a.panel_group) = UPPER(p_panel_hint));

    IF v_hits > 0 THEN
        RETURN QUERY
        SELECT a.analyte_code, a.analyte_name, a.panel_group, a.default_unit,
               CASE WHEN v_hits = 1 THEN 'EXACT' ELSE 'AMBIGUOUS' END::VARCHAR(20),
               1.000::NUMERIC
        FROM   config.lab_analyte_synonyms s
        JOIN   config.lab_analytes a ON a.analyte_code = s.analyte_code
        WHERE  s.match_key = v_key
          AND  s.is_active AND NOT s.is_deleted AND a.is_active AND NOT a.is_deleted
          AND  (p_panel_hint IS NULL OR UPPER(a.panel_group) = UPPER(p_panel_hint));
        RETURN;
    END IF;

    RETURN QUERY
    SELECT a.analyte_code, a.analyte_name, a.panel_group, a.default_unit,
           'FUZZY'::VARCHAR(20), ROUND(MAX(similarity(s.match_key, v_key))::NUMERIC, 3)
    FROM   config.lab_analyte_synonyms s
    JOIN   config.lab_analytes a ON a.analyte_code = s.analyte_code
    WHERE  s.is_active AND NOT s.is_deleted
      AND  a.is_active AND NOT a.is_deleted
      AND  (p_panel_hint IS NULL OR UPPER(a.panel_group) = UPPER(p_panel_hint))
      AND  similarity(s.match_key, v_key) >= p_threshold
    GROUP BY a.analyte_code, a.analyte_name, a.panel_group, a.default_unit
    ORDER BY 6 DESC
    LIMIT 5;
END;
$$;

-- Labels that legitimately map to more than one analyte. The resolver returns
-- match_type AMBIGUOUS for these and the staff screen must ask. Passing a
-- panel hint from the document classifier usually collapses them to one.
--   TC       -> CHOL (lipid) or WBC (total count)
--   CA       -> CA (total calcium) or CA_ION (ionised)
--   ALBUMIN  -> ALB (serum) or UR_PROT (urine dipstick)
-- Never resolve these silently.

-- Rows a lab sent that never matched. Review weekly; every row here is a
-- synonym waiting to be added.
CREATE TABLE IF NOT EXISTS config.lab_analyte_unmapped (
    unmapped_id     BIGSERIAL    PRIMARY KEY,
    raw_label       VARCHAR(200) NOT NULL,
    match_key       VARCHAR(200) NOT NULL,
    lab_name        VARCHAR(160),
    practice_id     BIGINT       NOT NULL,
    occurrences     INTEGER      NOT NULL DEFAULT 1,
    resolved_to     VARCHAR(40),
    first_seen_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_seen_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_by      VARCHAR(60)  NOT NULL DEFAULT 'SYSTEM',
    updated_at      TIMESTAMPTZ,
    updated_by      VARCHAR(60)
);
CREATE INDEX IF NOT EXISTS ix_unmapped_key ON config.lab_analyte_unmapped (match_key);
